DiyTables.SubmitBeforeServerV8:
/*
 * V8 Event
 * TableKey: sys_dept
 * EventType: SubmitBeforeServerV8
 * Version: v1.0.1
 * Function:
 * - 组织机构提交前：管理员边界、旧表审计字段兼容、父子循环与删除保护，并生成层级编码。
 */

var currentUser = V8.CurrentUser || {};
var isAdministrator = currentUser._IsAdmin === true
    || currentUser._IsAdmin === 1
    || String(currentUser._IsAdmin || '').toLowerCase() == 'true';
if (!isAdministrator) {
    return { Code: 0, Msg: '权限不足：只有平台管理员可以维护组织机构。' };
}

var action = String(V8.FormSubmitAction || '');
if (action == 'Insert') action = 'Add';
if (action == 'Update') action = 'Upt';
if (action == 'Delete') action = 'Del';
var form = V8.Form || {};
var oldForm = V8.OldForm || {};
var rootGuid = '00000000-0000-0000-0000-000000000000';
var rootUlid = '00000000000000000000000000';
function isRootId(value) {
    var text = String(value || '');
    return !text || text == rootGuid || text == rootUlid;
}

var deptId = String(form.Id || oldForm.Id || '');
if (action == 'Del') {
    if (!deptId) return { Code: 0, Msg: '组织机构 Id 不能为空。' };
    var childResult = V8.FormEngine.GetTableData('sys_dept', {
        _Where: [['ParentId', '=', deptId]],
        _SelectFields: ['Id'],
        _PageIndex: 1,
        _PageSize: 1
    }, V8.DbTrans);
    if (!childResult || childResult.Code != 1) return childResult;
    if ((childResult.DataCount || 0) > 0) {
        return { Code: 0, Msg: '当前组织机构存在下级数据，禁止删除。' };
    }
    return { Code: 1 };
}

var deptName = String(form.Name || '').trim();
if (!deptName) return { Code: 0, Msg: '组织机构名称不能为空。' };
form.Name = deptName;
if (action == 'Add' && (form.State === null || form.State === undefined || form.State === '')) form.State = 1;
var nowText = DateNow('yyyy-MM-dd HH:mm:ss');
if (action == 'Add') {
    if (!form.CreateTime) form.CreateTime = nowText;
    if (!form.UpdateTime) form.UpdateTime = nowText;
    if (form.IsDeleted === null || form.IsDeleted === undefined || form.IsDeleted === '') form.IsDeleted = 0;
} else if (action == 'Upt') {
    form.UpdateTime = nowText;
}
if (currentUser.TenantId) {
    form.TenantId = currentUser.TenantId;
    form.TenantName = currentUser.TenantName || '';
}

var parentId = isRootId(form.ParentId) ? rootGuid : String(form.ParentId);
form.ParentId = parentId;
if (deptId && parentId.toLowerCase() == deptId.toLowerCase()) {
    return { Code: 0, Msg: '组织机构不能把自己设置为上级。' };
}

var allDeptResult = V8.FormEngine.GetTableData('sys_dept', {
    _SelectFields: ['Id', 'ParentId', 'Code', 'Sort'],
    _OrderBy: 'Sort',
    _OrderByType: 'ASC',
    _PageIndex: 1,
    _PageSize: 10000
}, V8.DbTrans);
if (!allDeptResult || allDeptResult.Code != 1) return allDeptResult;
var allDepts = allDeptResult.Data || [];
var parent = null;
for (var parentIndex = 0; parentIndex < allDepts.length; parentIndex++) {
    if (String(allDepts[parentIndex].Id || '').toLowerCase() == parentId.toLowerCase()) {
        parent = allDepts[parentIndex];
        break;
    }
}
if (!isRootId(parentId) && !parent) return { Code: 0, Msg: '上级组织机构不存在。' };

var oldCode = String(oldForm.Code || '');
if (action == 'Upt' && parent && oldCode && String(parent.Code || '').indexOf(oldCode) === 0) {
    return { Code: 0, Msg: '不能将组织机构的父级调整到自身或下级组织机构。' };
}

var parentChanged = action == 'Add' || String(oldForm.ParentId || rootGuid) != parentId;
if (parentChanged || !form.Code) {
    var prefix = parent ? String(parent.Code || '') : '';
    if (parent && !prefix) return { Code: 0, Msg: '上级组织机构 Code 为空，请先修复上级组织机构。' };
    var maxSiblingNo = 0;
    for (var siblingIndex = 0; siblingIndex < allDepts.length; siblingIndex++) {
        var sibling = allDepts[siblingIndex];
        if (deptId && String(sibling.Id || '').toLowerCase() == deptId.toLowerCase()) continue;
        var siblingParentId = String(sibling.ParentId || rootGuid);
        if ((isRootId(parentId) && !isRootId(siblingParentId))
            || (!isRootId(parentId) && siblingParentId.toLowerCase() != parentId.toLowerCase())) continue;
        var siblingCode = String(sibling.Code || '');
        if (prefix && siblingCode.indexOf(prefix) !== 0) continue;
        var suffix = siblingCode.substring(prefix.length).replace(/-/g, '');
        var siblingNo = parseInt(suffix, 10);
        if (!isNaN(siblingNo) && siblingNo > maxSiblingNo) maxSiblingNo = siblingNo;
    }
    form.Code = prefix + (maxSiblingNo + 1) + '-';
}

return { Code: 1 };

