/*
 * V8 ApiEngine
 * ApiEngineKey: admin_get_empty_database_sanitization_sql
 * Version: v1.3.0
 * Function:
 * - 返回主库空数据库脱敏 SQL；按应用包归属清理业务资源，并清空租户私有设置、外部身份、身份治理、后台任务、备份、安装审计、消息配置等运行与敏感数据；完整资源由后端递归对账并在发布前执行零残留门禁。
 */

function text(value) { return value === null || value === undefined ? "" : String(value).trim(); }
function toArray(value) {
  var result = [];
  if (!value || value.length === undefined) return result;
  for (var i = 0; i < value.length; i++) result.push(value[i]);
  return result;
}
function addTable(map, value) {
  var name = text(value).replace(/^[`\"]+|[`\"]+$/g, "");
  if (/^[A-Za-z0-9_]+$/.test(name)) map[name.toLowerCase()] = name;
}
function visitJsonValues(value, visitor) {
  if (value && typeof value !== "string" && value.length !== undefined) {
    for (var valueIndex = 0; valueIndex < value.length; valueIndex++) {
      visitJsonValues(value[valueIndex], visitor);
    }
    return;
  }
  visitor(value);
}
function addEngineKey(map, value) {
  var key = text(value);
  if (/^[A-Za-z0-9_.:-]+$/.test(key)) map[key.toLowerCase()] = key;
}
function isCorePlatformApp(app) {
  var appKey = text(app.AppKey).toLowerCase();
  if (appKey === "microi-platform-service") return true;
  var runtimeType = text(app.ApplicationType);
  if (!runtimeType) runtimeType = text(app.AppType);
  if (runtimeType.toLowerCase() !== "platform") return false;
  return appKey.indexOf("app.microi.") === 0
    || appKey === "microi-wechat-content-security";
}

function collectPackageTableNames(store, map) {
  if (Number(store.PackageIsValid) !== 1) {
    return { Code: 0, Msg: "应用商城记录 " + text(store.Id) + " 的 AppPakcet 不是合法 JSON，已停止制作空库。" };
  }
  var nameJsonFields = [
    "SelectedTableNamesJson",
    "PackageDiyTableNamesJson"
  ];
  for (var fieldIndex = 0; fieldIndex < nameJsonFields.length; fieldIndex++) {
    var namesJson = text(store[nameJsonFields[fieldIndex]]);
    if (!namesJson) continue;
    var names;
    try { names = JSON.parse(namesJson); }
    catch (namesError) {
      return { Code: 0, Msg: "应用商城记录 " + text(store.Id) + " 的表清单无法解析，已停止制作空库。" };
    }
    visitJsonValues(names, function (name) { addTable(map, name); });
  }

  return { Code: 1 };
}

function collectPackageEngineKeys(store, map) {
  if (Number(store.PackageIsValid) !== 1) {
    return { Code: 0, Msg: "应用商城记录 " + text(store.Id) + " 的 AppPakcet 不是合法 JSON，已停止制作空库。" };
  }
  var keyJsonFields = [
    "SelectedApiEngineKeysJson",
    "PackageApiEngineKeysJson",
    "PackagePolicyEngineKeysJson"
  ];
  for (var fieldIndex = 0; fieldIndex < keyJsonFields.length; fieldIndex++) {
    var keysJson = text(store[keyJsonFields[fieldIndex]]);
    if (!keysJson) continue;
    var keys;
    try { keys = JSON.parse(keysJson); }
    catch (keysError) {
      return { Code: 0, Msg: "应用商城记录 " + text(store.Id) + " 的接口清单无法解析，已停止制作空库。" };
    }
    keys = toArray(keys);
    for (var keyIndex = 0; keyIndex < keys.length; keyIndex++) addEngineKey(map, keys[keyIndex]);
  }
  return { Code: 1 };
}

function getAllRows(tableName, selectFields, errorMessage, where) {
  var pageSize = 5000;
  var allRows = [];
  for (var pageIndex = 1; pageIndex <= 1000; pageIndex++) {
    var query = {
      _SelectFields: selectFields,
      _PageIndex: pageIndex,
      _PageSize: pageSize
    };
    if (where && where.length) query._Where = where;
    var result = V8.FormEngine.GetTableData(tableName, query);
    if (!result || result.Code !== 1) {
      return { Code: 0, Msg: (result && result.Msg) || errorMessage };
    }
    var pageRows = toArray(result.Data);
    for (var rowIndex = 0; rowIndex < pageRows.length; rowIndex++) allRows.push(pageRows[rowIndex]);
    if (pageRows.length < pageSize) return { Code: 1, Data: allRows };
  }
  return { Code: 0, Msg: tableName + " 数据超过 500 万行，已停止制作空库，避免生成不完整清理规则。" };
}

function getRowsByIds(tableName, ids, selectFields, errorMessage) {
  var allRows = [];
  for (var offset = 0; offset < ids.length; offset += 500) {
    var chunk = ids.slice(offset, offset + 500);
    var result = V8.FormEngine.GetTableData(tableName, {
      Ids: chunk,
      _SelectFields: selectFields,
      _PageIndex: 1,
      _PageSize: chunk.length
    });
    if (!result || result.Code !== 1) return { Code: 0, Msg: (result && result.Msg) || errorMessage };
    var rows = toArray(result.Data);
    for (var rowIndex = 0; rowIndex < rows.length; rowIndex++) allRows.push(rows[rowIndex]);
  }
  return { Code: 1, Data: allRows };
}

// AppPakcet 可能包含源码 ZIP Base64，整包读取会占用数百 MB 并触发 Jint 语句/内存上限。
// SelectTable/SelectApiEngine 作为快速清单；AppPakcet 仅投影轻量 DiyTables 和
// 接口资源。DiyFields、ApplicationBundles、DDL 等节点可能携带海量 TableName，
// 即使使用根路径也会触发 Jint 语句上限，因此完整表归属统一交给后端发布服务
// 对原始 AppPakcet 递归解析并做精确、幂等的对账清理。
var storeRows;
try {
  storeRows = toArray(V8.Db.FromSql(`
SELECT Id, AppKey, ApplicationType, AppType,
       CASE
         WHEN COALESCE(TRIM(AppPakcet), '') = '' THEN 1
         WHEN JSON_VALID(AppPakcet) THEN 1
         ELSE 0
       END AS PackageIsValid,
       CASE WHEN JSON_VALID(SelectTable)
         THEN JSON_EXTRACT(SelectTable, '$[*].Name')
         ELSE NULL END AS SelectedTableNamesJson,
       CASE WHEN JSON_VALID(AppPakcet)
         THEN JSON_EXTRACT(AppPakcet, '$.DiyTables[*].Name')
         ELSE NULL END AS PackageDiyTableNamesJson,
       CASE WHEN JSON_VALID(SelectApiEngine)
         THEN JSON_EXTRACT(SelectApiEngine, '$[*].ApiEngineKey')
         ELSE NULL END AS SelectedApiEngineKeysJson,
       CASE WHEN JSON_VALID(AppPakcet)
         THEN JSON_EXTRACT(AppPakcet, '$.SysApiEngines[*].ApiEngineKey')
         ELSE NULL END AS PackageApiEngineKeysJson,
       CASE WHEN JSON_VALID(AppPakcet)
         THEN JSON_EXTRACT(AppPakcet, '$.ResourcePolicies.ApiEngines[*].ApiEngineKey')
         ELSE NULL END AS PackagePolicyEngineKeysJson
FROM sys_microistore`).ToArray());
} catch (storeError) {
  return { Code: 0, Msg: "读取应用商城表清单失败，请确认主库为 MySQL 5.7+。" };
}
var tableMapsByStoreId = {};
var engineMapsByStoreId = {};
var platformTableMap = {};
var applicationTableMap = {};
var platformEngineMap = {};
var applicationEngineMap = {};
// 应用包的历史 SelectTable/AppPakcet 可能误带平台公共表。此白名单属于空库
// 生成器自身的安全边界：即使某个普通应用错误声明这些表的所有权，也不得把
