for (var diyIndex = 0; diyIndex < diyTableRows.length; diyIndex++) diyTableNameById[text(diyTableRows[diyIndex].Id)] = text(diyTableRows[diyIndex].Name);
for (var menuIndex = 0; menuIndex < menuRows.length; menuIndex++) {
  var menu = menuRows[menuIndex] || {};
  var menuTableMap = tableMapsByStoreId[text(menu.StoreId)];
