  addTable(menuTableMap, text(menu.DiyTableName) || diyTableNameById[text(menu.DiyTableId)]);
}
for (var classifyIndex = 0; classifyIndex < storeRows.length; classifyIndex++) {
  var classifyStore = storeRows[classifyIndex] || {};
