SELECT ApiEngineKey FROM sys_apiengine
WHERE LEFT(LOWER(COALESCE(ApiEngineKey, '')), 9) = 'mci_demo_'`).ToArray());
} catch (evidenceEngineError) {
  return { Code: 0, Msg: "读取 mci_demo 实测接口清单失败，已停止制作空库。" };
}
for (var evidenceIndex = 0; evidenceIndex < evidenceEngineRows.length; evidenceIndex++) {
  addEngineKey(applicationEngineMap, evidenceEngineRows[evidenceIndex] && evidenceEngineRows[evidenceIndex].ApiEngineKey);
}
for (var platformKey in platformTableMap) if (Object.prototype.hasOwnProperty.call(platformTableMap, platformKey)) delete applicationTableMap[platformKey];
for (var platformEngineKey in platformEngineMap) if (Object.prototype.hasOwnProperty.call(platformEngineMap, platformEngineKey)) delete applicationEngineMap[platformEngineKey];
var applicationTableNames = [];
for (var applicationKey in applicationTableMap) {
  if (Object.prototype.hasOwnProperty.call(applicationTableMap, applicationKey)) applicationTableNames.push(applicationTableMap[applicationKey]);
}
applicationTableNames.sort();
var applicationEngineKeys = [];
for (var applicationEngineKey in applicationEngineMap) {
  if (Object.prototype.hasOwnProperty.call(applicationEngineMap, applicationEngineKey)) applicationEngineKeys.push(applicationEngineMap[applicationEngineKey]);
}
applicationEngineKeys.sort();
var applicationTableValuesSql = applicationTableNames.length
  ? "INSERT IGNORE INTO temp_app_owned_tables (Name) VALUES " + applicationTableNames.map(function (name) { return "('" + name.replace(/'/g, "''") + "')"; }).join(",") + ";"
  : "SELECT 1;";
var protectedPlatformTableNotInSql = protectedPlatformTableNames
  .map(function (name) { return "'" + name.replace(/'/g, "''").toLowerCase() + "'"; })
  .join(",");
var applicationEngineValuesSql = applicationEngineKeys.length
  ? "INSERT IGNORE INTO temp_app_owned_engines (KeyName) VALUES " + applicationEngineKeys.map(function (key) { return "('" + key.replace(/'/g, "''") + "')"; }).join(",") + ";"
  : "SELECT 1;";

// 应用商城、AI 应用和 Quartz 表会随安装版本而变化。空库复制前后使用同一套
// 物理表结构，因此在主库读取一次存在性并据此生成 SQL，避免缺少可选表时
// 整个发布回滚；核心表仍保持强校验，不能用此机制掩盖核心结构损坏。
var optionalPhysicalTableNames = [
  "sys_microiservice", "sys_microiservice_page",
  "mci_ai_app_file", "mci_ai_app_version", "mci_ai_app",
  "mci_ai_project_file", "mci_ai_project",
  "sys_microistoreversion", "sys_appinstalled",
  "microi_job_cron_triggers", "microi_job_triggers", "microi_job_job_details"
].concat(operationalResidueTableNames);
var optionalPhysicalTableMap = {};
var skippedOptionalTables = [];
try {
  var optionalRows = toArray(V8.Db.FromSql(`
SELECT LOWER(table_name) AS TableName
FROM information_schema.tables
WHERE table_schema = DATABASE()
  AND LOWER(table_name) IN (
    'sys_microiservice','sys_microiservice_page',
    'mci_ai_app_file','mci_ai_app_version','mci_ai_app',
    'mci_ai_project_file','mci_ai_project',
    'sys_microistoreversion','sys_appinstalled',
    'microi_job_cron_triggers','microi_job_triggers','microi_job_job_details',
    'mci_background_task','mci_database_backup','mci_gitee_star_audit',
    'mci_system_setting','mci_user_external_identity','mci_user_access_key','diy_sso',
    'mci_identity_connector','mci_identity_credential','mci_identity_device','mci_identity_face',
    'mci_identity_group','mci_identity_group_member','mci_identity_sync_conflict','mci_identity_sync_run',
    'mci_identity_tag','mci_identity_tag_assignment','mci_identity_totp',
    'mci_ai_token_account','mci_file_remote_connection','mci_spider_account','mci_redis_connection',
    'sys_servernode','sys_sourcedatatable','microi_database','wx_mp','wx_menu',
    'mci_marketplace_install_event','mci_tenant_quota_log','mic_msg_event_log',
    'microi_job_locks','wx_mini_program','wx_tpl_msg','mic_msgset'
  )`).ToArray());
  for (var optionalIndex = 0; optionalIndex < optionalRows.length; optionalIndex++) {
    optionalPhysicalTableMap[text(optionalRows[optionalIndex] && optionalRows[optionalIndex].TableName).toLowerCase()] = true;
  }
} catch (optionalTableError) {
  return { Code: 0, Msg: "读取可选应用物理表清单失败，已停止制作空库。" };
}
for (var optionalNameIndex = 0; optionalNameIndex < optionalPhysicalTableNames.length; optionalNameIndex++) {
  var optionalName = optionalPhysicalTableNames[optionalNameIndex];
  if (!optionalPhysicalTableMap[optionalName]) skippedOptionalTables.push(optionalName);
}
function optionalSql(requiredTables, sql) {
  for (var requiredIndex = 0; requiredIndex < requiredTables.length; requiredIndex++) {
    if (!optionalPhysicalTableMap[text(requiredTables[requiredIndex]).toLowerCase()]) return "";
  }
  return sql;
}

