(function () {
  'use strict';

  var BINDING_RECOVERY_HOURS = 2;
  var CREATE_GRANT_TTL_SECONDS = 600;
  var TRANSFER_LOCK_TTL_SECONDS = 180;
  var STAR_PAGE_SIZE = 100;
  var STAR_PAGE_LIMIT = 20;
  var BINDING_FAILURE_REASONS = [
    'gitee_account_already_bound',
    'gitee_account_transfer_available'
  ];

  function trim(value) {
