    var parsedStarCount = parseInt(expectedStarCount || 0, 10);
    var expectedPages = !isNaN(parsedStarCount) && parsedStarCount > 0
      ? Math.ceil(parsedStarCount / STAR_PAGE_SIZE)
      : STAR_PAGE_LIMIT;
    var maxPages = Math.max(1, Math.min(expectedPages, STAR_PAGE_LIMIT));
    var page;
    for (page = 1; page <= maxPages; page += 1) {
      var url = page === 1
        ? 'https://gitee.com/' + encodeURIComponent(giteeLogin) + '/starred?per_page=' + STAR_PAGE_SIZE
        : 'https://gitee.com/' + encodeURIComponent(giteeLogin)
          + '/stared_projects?page=' + page + '&per_page=' + STAR_PAGE_SIZE;
