          }
        });
      } catch (ex) {
        return { Code: 2, Reason: 'star_page_temporarily_unavailable' };
      }
      if (Number(response.StatusCode || 0) !== 200) {
        return { Code: 2, Reason: 'star_page_temporarily_unavailable' };
      }
      var lowerHtml = String(response.Content || '').toLowerCase();
      var isStarPage = lowerHtml.indexOf('action_name":"stared_projects"') >= 0
        || lowerHtml.indexOf("<div class='project-list'>") >= 0
        || lowerHtml.indexOf('<div class="project-list">') >= 0;
      if (!isStarPage) return { Code: 2, Reason: 'star_page_response_invalid' };
      if (lowerHtml.indexOf('href="' + targetPath + '"') >= 0
          || lowerHtml.indexOf('href="https://gitee.com' + targetPath + '"') >= 0
          || lowerHtml.indexOf("href='" + targetPath + "'") >= 0) {
        return { Code: 1, EvidenceSource: 'current_star_page' };
