        Content: JSON.stringify({
          SourceUserId: sourceUserId,
          TargetUserId: currentUserId,
          GiteeUserId: evidence.GiteeUserId,
          GiteeLogin: evidence.GiteeLogin,
          Repository: repository,
          EvidenceSource: evidence.EvidenceSource,
          Time: verifiedAt
